"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[95332],{3331:(e,r,i)=>{i.d(r,{R:()=>o,x:()=>a});var t=i(36672);const n={},s=t.createContext(n);function o(e){const r=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function a(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:o(e.components),t.createElement(s.Provider,{value:r},e.children)}},29236:(e,r,i)=>{i.r(r),i.d(r,{assets:()=>l,contentTitle:()=>a,default:()=>m,frontMatter:()=>o,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"2023/03/30","title":"2023-03-30","description":"Homogenisering af design Homogenisering af design: Fordele og ulemper","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/03/30.md","sourceDirName":"2023/03","slug":"/2023/03/30","permalink":"/da/2023/03/30","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/03/30.md","tags":[],"version":"current","frontMatter":{"localized_date":"30. marts 2023","top_news":"Homogenisering af design: Fordele og ulemper: Homogenisering af design: Fordele og ulemper"},"sidebar":"defaultSidebar","previous":{"title":"2023-03-31","permalink":"/da/2023/03/31"},"next":{"title":"2023-03-29","permalink":"/da/2023/03/29"}}');var n=i(23420),s=i(3331);const o={localized_date:"30. marts 2023",top_news:"Homogenisering af design: Fordele og ulemper: Homogenisering af design: Fordele og ulemper"},a="2023-03-30",l={},d=[{value:"Homogenisering af design: Fordele og ulemper: Homogenisering af design: Fordele og ulemper",id:"homogenisering-af-design-fordele-og-ulemper-homogenisering-af-design-fordele-og-ulemper",level:2},{value:"Binance Struggles &amp; Crypto Debat om legitimitet",id:"binance-struggles--crypto-debat-om-legitimitet",level:2},{value:"Picsart AI frigiver Text2video-Zero v\xe6rkt\xf8j til syntetiske videoer",id:"picsart-ai-frigiver-text2video-zero-v\xe6rkt\xf8j-til-syntetiske-videoer",level:2},{value:"Ubuntu dropper Flatpak til Snap: Linux-f\xe6llesskabet reagerer",id:"ubuntu-dropper-flatpak-til-snap-linux-f\xe6llesskabet-reagerer",level:2},{value:"Cooler Master Case konverterer Framework Laptop til $39 Desktop",id:"cooler-master-case-konverterer-framework-laptop-til-39-desktop",level:2},{value:"Disney lukker Metaverse ned midt i kritik og skepsis",id:"disney-lukker-metaverse-ned-midt-i-kritik-og-skepsis",level:2},{value:"Sam Bankman-Fried&#39;s forsvar finansieret med gaffepenge",id:"sam-bankman-frieds-forsvar-finansieret-med-gaffepenge",level:2},{value:"Brug af ChatGPT til produktivitet i softwareudvikling",id:"brug-af-chatgpt-til-produktivitet-i-softwareudvikling",level:2},{value:"Programmeringssproglige s\xe6rheder: &quot;Wat&quot;-f\xe6nomenet",id:"programmeringssproglige-s\xe6rheder-wat-f\xe6nomenet",level:2},{value:"Google begik &quot;bevis\xf8del\xe6ggelse&quot; og l\xf8j, fastsl\xe5r en amerikansk dommer",id:"google-begik-bevis\xf8del\xe6ggelse-og-l\xf8j-fastsl\xe5r-en-amerikansk-dommer",level:2}];function g(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(r.header,{children:(0,n.jsx)(r.h1,{id:"2023-03-30",children:"2023-03-30"})}),"\n",(0,n.jsx)(r.h2,{id:"homogenisering-af-design-fordele-og-ulemper-homogenisering-af-design-fordele-og-ulemper",children:"Homogenisering af design: Fordele og ulemper: Homogenisering af design: Fordele og ulemper"}),"\n",(0,n.jsxs)(r.p,{children:["Artiklen diskuterer tendensen til homogenisering af design og \xe6stetik og fremh\xe6ver dens fordele og ulemper. Konvergensen af design skyldes b\xe5de kundernes og producenternes pr\xe6ferencer og er tydelig i forskellige brancher, herunder bilproduktion, arkitektur og branding. Diskussionen rejser sp\xf8rgsm\xe5l om balancen mellem optimering og kreativitet i design og forretning og de potentielle begr\xe6nsninger, som homogeniseringen udg\xf8r for innovation og individualitet. Artiklen udfordrer ideen om, at folk rundt om i verden \xf8nsker de samme ting, og argumenterer for, at realiseringen af \xf8nsker varierer fra kultur til kultur. Moodboard-effekten har f\xf8rt til blanding, men der er en mulighed for modige, originale m\xe6rker og virksomheder for at skille sig ud.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35355703",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,n.jsx)(r.a,{href:"https://www.alexmurrell.co.uk/articles/the-age-of-average",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"binance-struggles--crypto-debat-om-legitimitet",children:"Binance Struggles & Crypto Debat om legitimitet"}),"\n",(0,n.jsxs)(r.p,{children:["Binance k\xe6mper, da det st\xe5r over for 2 milliarder dollars i udstr\xf8mning, reguleringsforbud og kritik for lyssky praksis. I mellemtiden forts\xe6tter debatten om legitimiteten af kryptovalutaer og NFT'er med kritik af nogle udvekslinger og projekter for r\xf8de flag som uregistrerede v\xe6rdipapirer og manglende overholdelse af regler. Diskussionen omfatter ogs\xe5 argumenter for og imod regulering af krypto og de potentielle risici forbundet med at investere i dem. Den amerikanske CFTC sags\xf8gte for nylig Binance p\xe5 grund af p\xe5stande om ulovlig amerikansk drift og overtr\xe6delse af handelsreglerne. P\xe5 trods af bekymringer forbliver Binances BNB-token stort set up\xe5virket, mens branchen som helhed oplever mere reguleringstilsyn.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35351805",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,n.jsx)(r.a,{href:"https://www.wsj.com/articles/binance-sees-2-billion-in-outflows-as-troubles-compound-9a136e21",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"picsart-ai-frigiver-text2video-zero-v\xe6rkt\xf8j-til-syntetiske-videoer",children:"Picsart AI frigiver Text2video-Zero v\xe6rkt\xf8j til syntetiske videoer"}),"\n",(0,n.jsxs)(r.p,{children:["Picsart AI Research har frigivet Text2Video-Zero, et v\xe6rkt\xf8j, der genererer syntetiske videoer ud fra inputtekst ved hj\xe6lp af naturlig sprogbehandling. Koden og v\xe6gtene til modellen er tilg\xe6ngelige, s\xe5 enkeltpersoner kan k\xf8re deres egen instans af softwaren p\xe5 et system med mindst 12 GB VRAM. Udgivelsen har vakt interesse i det generative AI-f\xe6llesskab p\xe5 trods af nogle sarkastiske kommentarer. Der er dog begr\xe6nsninger for AI, n\xe5r det g\xe6lder om at skabe kunst, der taler til menneskelige behov og f\xf8lelser, og AI-modeller kan ikke erstatte menneskelige VFX-kunstneres kreative og kunstneriske visioner. V\xe6rkt\xf8jet Text-to-Video with Edge Guidance genererer videoer fra tekstinput, herunder forskellige stilarter, og det er tilg\xe6ngeligt p\xe5 GitHub under CreativeML Open RAIL-M-licensen.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35352452",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,n.jsx)(r.a,{href:"https://github.com/Picsart-AI-Research/Text2Video-Zero",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"ubuntu-dropper-flatpak-til-snap-linux-f\xe6llesskabet-reagerer",children:"Ubuntu dropper Flatpak til Snap: Linux-f\xe6llesskabet reagerer"}),"\n",(0,n.jsxs)(r.p,{children:["Canonical har indstillet underst\xf8ttelsen af Flatpak og satser nu udelukkende p\xe5 Snap, hvilket skaber kontroverser blandt Linux-brugere, der kritiserer Snaps langsomme opdateringsmekanismer og begr\xe6nsninger. Brugerne er g\xe5et over til alternative distributioner som Fedora og Linux Mint eller anbefaler ikke-frie Debian-images og PopOS til andre for at l\xf8se driverproblemer. Samtalen fremh\xe6ver vigtigheden af brugerkontrol og valgmuligheder, hvorvidt applikationsudviklere eller distroer b\xf8r pakke software og behovet for standardiserede pakkeformater. Nogle brugere foretr\xe6kker Flatpak frem for Snap og udtrykker bekymring over Canonicals beslutning, mens andre ser v\xe6rdien i begge systemer for \xe6ldre versioner af Linux-distributioner.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35354729",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,n.jsx)(r.a,{href:"https://lwn.net/SubscriberLink/927262/6adb2350e2b0d2ce/",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"cooler-master-case-konverterer-framework-laptop-til-39-desktop",children:"Cooler Master Case konverterer Framework Laptop til $39 Desktop"}),"\n",(0,n.jsxs)(r.p,{children:["Cooler Master tilbyder et kabinet til 39 dollars, der forvandler en gammel Framework Laptop til en desktop PC med udvidelig lagerplads og en standard ATX str\xf8mforsyning. Hacker News-brugere er glade for id\xe9en om at genbruge gamle b\xe6rbare dele, men diskuterer ogs\xe5 genbrug og reduktion af e-affald. Framework har til form\xe5l at spare forbrugerne penge med udvidelige CPU- og lagermuligheder og reducere e-affaldet. Virksomheden lancerer ogs\xe5 en DIY-desktop-pc til en pris p\xe5 999 dollars som en modul\xe6r, str\xf8mbesparende og tilpasselig platform. Framework Laptop, en b\xe6rbar computer med \xe5ben kildekode, der kan repareres og opgraderes, lanceres som et b\xe6redygtigt og \xf8konomisk overkommeligt alternativ til de traditionelle pc-producenter. Framework samarbejder med Cooler Master om den gennemsigtige kuffert til 39 USD og lancerer et proof-of-concept batterikasse og en batteripakke med h\xf8jere t\xe6thedsgrad til sine b\xe6rbare computere.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35350288",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,n.jsx)(r.a,{href:"https://www.theverge.com/2023/3/23/23652939/framework-cooler-master-sff-pc-case",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"disney-lukker-metaverse-ned-midt-i-kritik-og-skepsis",children:"Disney lukker Metaverse ned midt i kritik og skepsis"}),"\n",(0,n.jsxs)(r.p,{children:["Disney har lukket sin Metaverse-afdeling ned, hvilket har f\xf8rt til spekulationer om, at projektet var for risikabelt. Kritikere af virtual reality (VR) n\xe6vner bekymringer om bev\xe6gelsessyge, dyre headsets og social isolation. Nogle h\xe6vder, at VR's begr\xe6nsninger og ulemper g\xf8r det til et uhensigtsm\xe6ssigt koncept. Temaparkenes succes er baseret p\xe5 f\xf8lelsesm\xe6ssige forbindelser, som ikke kan gentages af VR-oplevelser. Lukningen af Metaverse-afdelingen har udl\xf8st diskussioner om VR's fremtid og potentialet i augmented reality-teknologien (AR). Ideen om Metaverse er blevet kritiseret for blot at v\xe6re et hype-tog. Disneys beslutning om at lukke divisionen tyder p\xe5, at Disney m\xe5ske har nedjusteret sine forventninger til Metaversets v\xe6kst. Kommentatorer er nysgerrige p\xe5 fremtiden for VR for medie- og underholdningsgiganten.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35350952",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,n.jsx)(r.a,{href:"https://www.wsj.com/articles/disney-eliminates-its-metaverse-division-as-part-of-companys-layoffs-plan-94b03650",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"sam-bankman-frieds-forsvar-finansieret-med-gaffepenge",children:"Sam Bankman-Fried's forsvar finansieret med gaffepenge"}),"\n",(0,n.jsxs)(r.p,{children:["FTX-stifter Sam Bankman-Fried finansierer angiveligt sit igangv\xe6rende forsvar i en retssag med penge, som han gav sin far, hvilket if\xf8lge nogle kommentarer p\xe5 Hacker News blev gennemf\xf8rt ved hj\xe6lp af regnskabstricks for at undg\xe5 skat. Advokater har et professionelt ansvar for at sikre, at de handler etisk korrekt og unders\xf8ger kilden til de midler, de f\xe5r udbetalt, da der er risiko for tilbagebetaling, da regeringen lovligt kan kr\xe6ve, at midlerne stammer fra udbytte fra kriminalitet. Nogle af kommentarerne til artiklen giver udtryk for bekymring over lovligheden af den kaution p\xe5 250 mio. USD, som Bankman-Fried har stillet sikkerhed for, samt om muligheden for beslagl\xe6ggelse af aktiver i tilf\xe6lde af kriminelle aktiviteter. Andre diskuterer fagfolks etik og kritiserer de h\xf8je gebyrer, som konkursforvaltere opkr\xe6ver i tilbagek\xf8bssager.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35358698",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,n.jsx)(r.a,{href:"https://www.forbes.com/sites/sarahemerson/2023/03/29/sam-bankman-fried-legal-fees-funded-by-alameda-money-gifted-to-father-joe-bankman/",children:"L\xe6s originaltekst"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"brug-af-chatgpt-til-produktivitet-i-softwareudvikling",children:"Brug af ChatGPT til produktivitet i softwareudvikling"}),"\n",(0,n.jsxs)(r.p,{children:["Brugen af OpenAI's ChatGPT bliver mere og mere udbredt inden for softwareudvikling, hvilket giver et betydeligt produktivitetsl\xf8ft, is\xe6r for \xe6ldre udviklere. Det vil dog ikke erstatte programm\xf8rer i den n\xe6rmeste fremtid, da kreativitet, probleml\xf8sningsevner og evnen til at arbejde godt i et team fortsat er afg\xf8rende. Investering i selvautomatisering og v\xe6rkt\xf8jsudvikling kan g\xf8re en person til en yderst produktiv og v\xe6rdifuld ingeni\xf8r. Artiklen indeholder praktiske eksempler p\xe5 brug af AI-teknologi til at \xf8ge produktiviteten inden for softwareudvikling. Kommentarer fra nogle erfarne programm\xf8rer afsl\xf8rer bekymringer om de potentielle ulemper ved AI-v\xe6rkt\xf8jer s\xe5som vedligeholdbarhed, fejlfinding og virkningen p\xe5 jobbet som softwareingeni\xf8r. Effektiviteten af 10x programm\xf8rkonceptet og kvaliteten af datalogiuddannelsen og ans\xe6ttelsesprocessen i den teknologiske industri diskuteres ogs\xe5 i kommentarerne.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35356054",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,n.jsx)(r.a,{href:"https://kadekillary.work/posts/1000x-eng/",children:"L\xe6s originalteksten"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"programmeringssproglige-s\xe6rheder-wat-f\xe6nomenet",children:'Programmeringssproglige s\xe6rheder: "Wat"-f\xe6nomenet'}),"\n",(0,n.jsxs)(r.p,{children:['Artiklen fremh\xe6ver "WAT"-f\xe6nomenet i programmeringssprog, hvor s\xe6rheder i adf\xe6rd kan v\xe6re forvirrende eller uventede. Der henvises til et indl\xe6g i Hacker News og en Reddit-tr\xe5d, der diskuterer m\xe6rkelig adf\xe6rd i henholdsvis JavaScript og Python. Diskussionen afspejler den l\xf8bende udvikling af programmeringssprog og betydningen af kontekst, konsistens og l\xe6sbarhed. I artiklen diskuteres ogs\xe5 en video af Gary Bernhardt kaldet "WAT", som viser nogle af de m\xe6rkv\xe6rdige ting i JavaScript. Mange kommentatorer beundrer videoen for dens kreative tilgang til trods for, at den anerkender sprogets s\xe6rheder.\n',(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35363044",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,n.jsx)(r.a,{href:"https://www.destroyallsoftware.com/talks/wat",children:"L\xe6s originalteksten"}),"."]}),"\n",(0,n.jsx)(r.h2,{id:"google-begik-bevis\xf8del\xe6ggelse-og-l\xf8j-fastsl\xe5r-en-amerikansk-dommer",children:'Google begik "bevis\xf8del\xe6ggelse" og l\xf8j, fastsl\xe5r en amerikansk dommer'}),"\n",(0,n.jsxs)(r.p,{children:["En amerikansk forbundsdommer fandt, at Google \xf8delagde bevismateriale og l\xf8j over for retten i en afg\xf8relse med alvorlige konsekvenser i antitrustsager. Dommeren fastslog, at Google-ansatte rutinem\xe6ssigt diskuterede v\xe6sentlige forretningsemner, hvilket kan f\xf8re til en negativ konklusion, der indikerer, at de slettede beviser var imod Google. Dommen vedr\xf8rer retssager fra Epic Games og justitsministeriet. Google undlod at opbevare chatoptegnelser fra n\xf8glemedarbejdere, og dommeren har endnu ikke sanktioneret Google, men der vil blive fastsat b\xf8der, n\xe5r unders\xf8gelsen af de faktiske omst\xe6ndigheder er afsluttet. Virksomheder er ansvarlige for de handlinger, som deres medarbejdere foretager, og personer, der er ansvarlige for at \xf8del\xe6gge bevismateriale, b\xf8r stilles til ansvar. I kommentarerne foresl\xe5s en graduering af b\xf8derne p\xe5 grundlag af virksomhedens oms\xe6tning i lighed med bankernes b\xf8der for hvidvaskning af penge og bek\xe6mpelse af terrorisme.\n",(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35363095",children:"Diskuter p\xe5 Discussion Service"})," eller ",(0,n.jsx)(r.a,{href:"https://storage.courtlistener.com/recap/gov.uscourts.cand.373179/gov.uscourts.cand.373179.469.0.pdf",children:"L\xe6s originalteksten"}),"."]})]})}function m(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,n.jsx)(r,{...e,children:(0,n.jsx)(g,{...e})}):g(e)}}}]);